"use client"

/**
 * Clean-room task board for any CRM.
 * Columns, priority counts, search, board or list, and a detail sheet.
 * Pass records in. Saves go through callbacks and stay on the host.
 * `view-kanban` remains the schema board inside multi-view.
 */

import * as React from "react"
import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  closestCorners,
  useDroppable,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
} from "@dnd-kit/core"
import {
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable"
import { CSS as DndCSS } from "@dnd-kit/utilities"
import { LayoutGrid, List, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetTitle,
} from "@/components/ui/sheet"
import { SearchField } from "@/components/ui/search-field"
import { SegmentedControl } from "@/components/ui/segmented-control"
import { TaskCard } from "@/components/ui/task-card"
import { TaskDetail } from "@/components/ui/task-detail"
import {
  adjacentTaskId,
  countTasksByPriority,
  defaultPriorities,
  defaultSubtaskStatuses,
  groupTasksByStage,
  isTaskOverdue,
  orderTasks,
  resolveTaskBoardLabels,
  taskMatchesQuery,
  taskToneDot,
  type TaskBoardLabels,
  type TaskBoardView,
  type TaskCommentInput,
  type TaskOption,
  type TaskPatch,
  type TaskPerson,
  type TaskPriority,
  type TaskRecord,
  type TaskStageGroup,
  type TaskSubtaskDraft,
} from "@/lib/task-board"

const STAGE_PREFIX = "stage:"

export type TaskBoardProps<TMeta = Record<string, unknown>> = {
  tasks: readonly TaskRecord<TMeta>[]
  stages: readonly TaskOption[]
  categories?: readonly TaskOption[]
  people?: readonly TaskPerson[]
  priorities?: readonly { id: TaskPriority; label: string }[]
  subtaskStatuses?: readonly TaskOption[]
  /** Stages where a past date is not overdue. */
  doneStageIds?: readonly string[]
  view?: TaskBoardView
  defaultView?: TaskBoardView
  onViewChange?: (view: TaskBoardView) => void
  query?: string
  defaultQuery?: string
  onQueryChange?: (query: string) => void
  /** Priority id, or null when the summary is not filtering. */
  priority?: TaskPriority | null
  defaultPriority?: TaskPriority | null
  onPriorityChange?: (priority: TaskPriority | null) => void
  selectedId?: string | null
  defaultSelectedId?: string | null
  onSelectedIdChange?: (id: string | null) => void
  /** Preferred path when a task changes column. */
  onMove?: (id: string, toStageId: string, fromStageId: string) => void | Promise<void>
  onUpdate?: (id: string, patch: TaskPatch<TMeta>) => void | Promise<void>
  onAddSubtask?: (id: string, draft: TaskSubtaskDraft) => void | Promise<void>
  onSubtaskStatusChange?: (taskId: string, subtaskId: string, statusId: string) => void | Promise<void>
  onComment?: (id: string, input: TaskCommentInput) => void | Promise<void>
  onAttach?: (id: string, files: readonly File[]) => void | Promise<void>
  onRemoveAttachment?: (taskId: string, attachmentId: string) => void | Promise<void>
  onCreateRequest?: (stageId: string) => void
  onRetry?: () => void
  readOnly?: boolean
  loading?: boolean
  error?: string | null
  /** ISO string or Date. Defaults to the current time, so overdue follows the clock. */
  now?: Date | string
  locale?: string
  labels?: Partial<TaskBoardLabels>
  className?: string
  toolbarClassName?: string
  columnClassName?: string
  cardClassName?: string
  sheetClassName?: string
}

export function TaskBoard<TMeta extends Record<string, unknown> = Record<string, unknown>>({
  tasks,
  stages,
  categories = [],
  people = [],
  priorities,
  subtaskStatuses,
  doneStageIds = [],
  view: viewProp,
  defaultView = "board",
  onViewChange,
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  priority: priorityProp,
  defaultPriority = null,
  onPriorityChange,
  selectedId: selectedIdProp,
  defaultSelectedId = null,
  onSelectedIdChange,
  onMove,
  onUpdate,
  onAddSubtask,
  onSubtaskStatusChange,
  onComment,
  onAttach,
  onRemoveAttachment,
  onCreateRequest,
  onRetry,
  readOnly = false,
  loading = false,
  error = null,
  now,
  locale = "es",
  labels: labelOverrides,
  className,
  toolbarClassName,
  columnClassName,
  cardClassName,
  sheetClassName,
}: TaskBoardProps<TMeta>) {
  const labels = resolveTaskBoardLabels(labelOverrides)
  const priorityOptions = priorities ?? defaultPriorities(labels)
  const statusOptions = subtaskStatuses ?? defaultSubtaskStatuses(labels)
  const clock = now ?? new Date()
  const [view, setView] = useControllable(viewProp, defaultView, onViewChange)
  const [query, setQuery] = useControllable(queryProp, defaultQuery, onQueryChange)
  const [priority, setPriority] = useControllable(priorityProp, defaultPriority, onPriorityChange)
  const [selectedId, setSelectedId] = useControllable(selectedIdProp, defaultSelectedId, onSelectedIdChange)
  const [activeId, setActiveId] = React.useState<string | null>(null)
  const [announcement, setAnnouncement] = React.useState("")
  const [focusNonce, setFocusNonce] = React.useState(0)
  const focusId = React.useRef<string | null>(null)
  const reduced = usePrefersReducedMotion()
  const narrow = useNarrowScreen()

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  const searched = React.useMemo(
    () => tasks.filter((task) => taskMatchesQuery(task, query, { people, categories, stages })),
    [categories, people, query, stages, tasks],
  )
  const counts = React.useMemo(() => countTasksByPriority(searched), [searched])
  const visible = priority ? searched.filter((task) => task.priority === priority) : searched
  const groups = React.useMemo(() => groupTasksByStage(visible, stages), [stages, visible])
  const ordered = React.useMemo(() => orderTasks(tasks, stages), [stages, tasks])
  const orderedIds = React.useMemo(() => ordered.map((task) => task.id), [ordered])
  const selected = tasks.find((task) => task.id === selectedId) ?? null
  const selectedIndex = selected ? orderedIds.indexOf(selected.id) : -1
  const active = tasks.find((task) => task.id === activeId) ?? null

  const state = loading
    ? "loading"
    : error
      ? "error"
      : tasks.length === 0
        ? "empty"
        : visible.length === 0
          ? "nomatch"
          : "ready"

  React.useEffect(() => {
    const id = focusId.current
    if (!id) return
    focusId.current = null
    const escaped = typeof CSS !== "undefined" && typeof CSS.escape === "function" ? CSS.escape(id) : id
    document.querySelector<HTMLElement>(`[data-task-focus="${escaped}"]`)?.focus()
  }, [focusNonce])

  function stageLabel(id: string) {
    return stages.find((stage) => stage.id === id)?.label ?? id
  }

  function labelForDrag(id: string) {
    if (id.startsWith(STAGE_PREFIX)) return stageLabel(id.slice(STAGE_PREFIX.length))
    return tasks.find((task) => task.id === id)?.title ?? id
  }

  function moveTask(id: string, toStageId: string, source: "pointer" | "keyboard") {
    if (readOnly) return
    const task = tasks.find((item) => item.id === id)
    if (!task || task.stageId === toStageId) return
    if (source === "keyboard") {
      focusId.current = id
      setFocusNonce((nonce) => nonce + 1)
      setAnnouncement(labels.moved(task.title, stageLabel(toStageId)))
    }
    if (onMove) void onMove(id, toStageId, task.stageId)
    else void onUpdate?.(id, { stageId: toStageId })
  }

  function onDragStart(event: DragStartEvent) {
    setActiveId(String(event.active.id))
  }

  function onDragEnd(event: DragEndEvent) {
    setActiveId(null)
    const overId = event.over ? String(event.over.id) : ""
    const toStageId = resolveStageId(overId, tasks)
    if (!toStageId) return
    moveTask(String(event.active.id), toStageId, "pointer")
  }

  function select(id: string | null) {
    setSelectedId(id)
  }

  const previousId = selected ? adjacentTaskId(orderedIds, selected.id, -1) : null
  const nextId = selected ? adjacentTaskId(orderedIds, selected.id, 1) : null

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCorners}
      onDragStart={onDragStart}
      onDragEnd={onDragEnd}
      onDragCancel={() => setActiveId(null)}
      accessibility={{
        announcements: {
          onDragStart({ active: item }) {
            return labels.pickedUp(labelForDrag(String(item.id)))
          },
          onDragOver({ over }) {
            return over ? labels.overColumn(labelForDrag(String(over.id))) : ""
          },
          onDragEnd({ active: item, over }) {
            const title = labelForDrag(String(item.id))
            return over ? labels.moved(title, labelForDrag(String(over.id))) : labels.dropped
          },
          onDragCancel() {
            return labels.cancelled
          },
        },
      }}
    >
      <div
        data-slot="task-board"
        data-state={state}
        data-view={view}
        data-reduced-motion={reduced ? "true" : "false"}
        data-readonly={readOnly ? "true" : "false"}
        role="region"
        aria-label={labels.boardLabel}
        aria-busy={loading || undefined}
        className={cn("flex h-full w-full min-h-0 min-w-0 max-w-full flex-col gap-3", className)}
      >
        <div className={cn("flex shrink-0 flex-col gap-3", toolbarClassName)}>
          <div role="group" aria-label={labels.prioritySummary} className="grid grid-cols-2 gap-2 sm:grid-cols-4">
            {priorityOptions.map((item) => {
              const pressed = priority === item.id
              return (
                <button
                  key={item.id}
                  type="button"
                  aria-pressed={pressed}
                  aria-label={labels.filterPriority(item.label, counts[item.id])}
                  className={cn(
                    "flex min-w-0 items-center gap-2 rounded-xl border border-border bg-card px-3 py-2 text-left text-card-foreground",
                    "focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                    pressed && "ring-2 ring-ring",
                  )}
                  onClick={() => setPriority(pressed ? null : item.id)}
                >
                  <span className="min-w-0 flex-1 truncate text-sm text-muted-foreground">{item.label}</span>
                  <span className="text-lg font-semibold tabular-nums">{counts[item.id]}</span>
                </button>
              )
            })}
          </div>
          <div className="flex flex-col gap-2 sm:flex-row sm:items-end">
            <SearchField
              className="min-w-0 flex-1"
              label={labels.searchLabel}
              placeholder={labels.searchPlaceholder}
              value={query}
              onValueChange={setQuery}
            />
            <SegmentedControl
              className="shrink-0"
              label={labels.viewLabel}
              value={view}
              onValueChange={(next) => {
                if (next === "board" || next === "list") setView(next)
              }}
              options={[
                { value: "board", label: labels.boardView, icon: <LayoutGrid aria-hidden /> },
                { value: "list", label: labels.listView, icon: <List aria-hidden /> },
              ]}
            />
          </div>
          {readOnly ? (
            <p className="text-xs text-muted-foreground" role="status">
              {labels.readOnlyNote}
            </p>
          ) : null}
        </div>

        {state === "loading" ? (
          <div role="status" aria-label={labels.loadingLabel} className="flex min-h-0 w-full min-w-0 flex-1 gap-3 overflow-x-auto">
            {Array.from({ length: 3 }, (_, index) => (
              <div key={index} className="flex w-72 shrink-0 flex-col gap-2 rounded-xl bg-muted/40 p-2">
                <Skeleton className="h-5 w-24" />
                <Skeleton className="h-24 w-full" />
                <Skeleton className="h-24 w-full" />
              </div>
            ))}
          </div>
        ) : null}

        {state === "error" ? (
          <div
            role="alert"
            className="flex min-h-40 flex-1 flex-col items-center justify-center gap-3 rounded-xl border border-dashed border-border p-6 text-center"
          >
            <p className="text-sm font-medium">{labels.errorTitle}</p>
            <p className="max-w-sm text-sm text-muted-foreground break-all">{error}</p>
            {onRetry ? (
              <Button type="button" onClick={onRetry}>
                {labels.retry}
              </Button>
            ) : null}
          </div>
        ) : null}

        {state === "empty" || state === "nomatch" ? (
          <div className="flex min-h-40 flex-1 flex-col items-center justify-center gap-1 rounded-xl border border-dashed border-border p-6 text-center">
            <p className="text-sm font-medium">{state === "empty" ? labels.emptyTitle : labels.noMatchesTitle}</p>
            <p className="max-w-sm text-sm text-muted-foreground">
              {state === "empty" ? labels.emptyHint : labels.noMatchesHint}
            </p>
          </div>
        ) : null}

        {state === "ready" && view === "board" ? (
          <div className="flex min-h-0 w-full min-w-0 flex-1 snap-x snap-mandatory gap-3 overflow-x-auto overscroll-x-contain pb-1">
            {groups.map((group) => (
              <StageColumn key={group.stage.id} id={`${STAGE_PREFIX}${group.stage.id}`} label={group.stage.label} className={cn("h-full", columnClassName)}>
                <ColumnHeader group={group} />
                <SortableContext items={group.tasks.map((task) => task.id)} strategy={verticalListSortingStrategy}>
                  <div className="flex min-h-24 flex-1 flex-col gap-2 overflow-y-auto">
                    {group.tasks.length === 0 ? (
                      <p className="px-1 py-6 text-center text-xs text-muted-foreground">{labels.noTasksInColumn}</p>
                    ) : (
                      group.tasks.map((task) => (
                        <SortableTask
                          key={task.id}
                          task={task}
                          reduced={reduced}
                          disabled={readOnly}
                          cardClassName={cardClassName}
                          people={people}
                          stages={stages}
                          priorities={priorityOptions}
                          overdue={isTaskOverdue(task, clock, doneStageIds)}
                          locale={locale}
                          labels={labels}
                          selected={task.id === selectedId}
                          onOpen={select}
                          onMoveTo={(stageId) => moveTask(task.id, stageId, "keyboard")}
                        />
                      ))
                    )}
                  </div>
                </SortableContext>
                {onCreateRequest && !readOnly ? (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="justify-start"
                    onClick={() => onCreateRequest(group.stage.id)}
                  >
                    <Plus aria-hidden />
                    {labels.addTask}
                  </Button>
                ) : null}
              </StageColumn>
            ))}
          </div>
        ) : null}

        {state === "ready" && view === "list" ? (
          <div className="flex min-h-0 w-full min-w-0 flex-1 flex-col gap-4 overflow-y-auto">
            {groups.map((group) => (
              <StageColumn
                key={group.stage.id}
                id={`${STAGE_PREFIX}${group.stage.id}`}
                label={group.stage.label}
                className={cn("h-auto w-full", columnClassName)}
              >
                <ColumnHeader group={group} />
                <SortableContext items={group.tasks.map((task) => task.id)} strategy={verticalListSortingStrategy}>
                  <div className="grid min-h-16 gap-2">
                    {group.tasks.length === 0 ? (
                      <p className="px-1 py-4 text-center text-xs text-muted-foreground">{labels.noTasksInColumn}</p>
                    ) : (
                      group.tasks.map((task) => (
                        <SortableTask
                          key={task.id}
                          task={task}
                          reduced={reduced}
                          disabled={readOnly}
                          cardClassName={cardClassName}
                          people={people}
                          stages={stages}
                          priorities={priorityOptions}
                          overdue={isTaskOverdue(task, clock, doneStageIds)}
                          locale={locale}
                          labels={labels}
                          selected={task.id === selectedId}
                          onOpen={select}
                          onMoveTo={(stageId) => moveTask(task.id, stageId, "keyboard")}
                        />
                      ))
                    )}
                  </div>
                </SortableContext>
              </StageColumn>
            ))}
          </div>
        ) : null}

        <div role="status" aria-live="polite" aria-atomic="true" data-slot="task-board-announcement" className="sr-only">
          {announcement}
        </div>
      </div>

      <DragOverlay dropAnimation={reduced ? null : undefined}>
        {active ? (
          <article className="rounded-lg border border-border bg-card p-3 shadow-md">
            <p className="line-clamp-2 text-sm font-medium break-all" dir="auto">
              {active.title}
            </p>
          </article>
        ) : null}
      </DragOverlay>

      <Sheet open={Boolean(selected)} onOpenChange={(open) => { if (!open) select(null) }}>
        <SheetContent
          side="right"
          showCloseButton={false}
          style={narrow ? { width: "100%", maxWidth: "none" } : { width: "32rem", maxWidth: "32rem" }}
          className={cn("gap-0 overflow-hidden p-0", sheetClassName)}
        >
          <SheetTitle className="sr-only">{labels.detailTitle}</SheetTitle>
          <SheetDescription className="sr-only">
            {selected ? `${selected.title}. ${labels.shortcuts}` : labels.detailTitle}
          </SheetDescription>
          {selected ? (
            <TaskDetail
                task={selected}
                people={people}
                stages={stages}
                categories={categories}
                priorities={priorityOptions}
                subtaskStatuses={statusOptions}
                position={selectedIndex + 1}
                total={ordered.length}
                locale={locale}
                labels={labels}
                readOnly={readOnly}
                onClose={() => select(null)}
                onPrevious={previousId ? () => select(previousId) : undefined}
                onNext={nextId ? () => select(nextId) : undefined}
                onUpdate={onUpdate}
                onStageChange={(stageId) => moveTask(selected.id, stageId, "keyboard")}
                onAddSubtask={onAddSubtask}
                onSubtaskStatusChange={onSubtaskStatusChange}
                onComment={onComment}
                onAttach={onAttach}
                onRemoveAttachment={onRemoveAttachment}
              />
          ) : null}
        </SheetContent>
      </Sheet>
    </DndContext>
  )
}

function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const current = value !== undefined ? value : uncontrolled
  const setValue = React.useCallback(
    (next: T) => {
      if (value === undefined) setUncontrolled(next)
      onChange?.(next)
    },
    [onChange, value],
  )
  return [current, setValue] as const
}

function useNarrowScreen() {
  const [narrow, setNarrow] = React.useState(true)
  React.useLayoutEffect(() => {
    const media = window.matchMedia("(max-width: 767px)")
    const apply = () => setNarrow(media.matches)
    apply()
    media.addEventListener("change", apply)
    return () => media.removeEventListener("change", apply)
  }, [])
  return narrow
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false)
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)")
    const apply = () => setReduced(media.matches)
    apply()
    media.addEventListener("change", apply)
    return () => media.removeEventListener("change", apply)
  }, [])
  return reduced
}

function resolveStageId<TMeta>(overId: string, tasks: readonly TaskRecord<TMeta>[]) {
  const overTask = tasks.find((task) => task.id === overId)
  if (overTask) return overTask.stageId
  if (overId.startsWith(STAGE_PREFIX)) return overId.slice(STAGE_PREFIX.length)
  return null
}

function ColumnHeader<TMeta>({ group }: { group: TaskStageGroup<TMeta> }) {
  const dot = taskToneDot(group.stage.tone)
  return (
    <header className="flex shrink-0 items-center gap-2 px-1">
      {dot ? <span className={cn("size-2 shrink-0 rounded-full", dot)} aria-hidden /> : null}
      <p className="min-w-0 flex-1 truncate text-sm font-medium">{group.stage.label}</p>
      <span className="rounded-full bg-background px-2 py-0.5 text-xs text-muted-foreground tabular-nums">
        {group.tasks.length}
      </span>
    </header>
  )
}

function StageColumn({
  id,
  label,
  className,
  children,
}: {
  id: string
  label: string
  className?: string
  children: React.ReactNode
}) {
  const { setNodeRef, isOver } = useDroppable({ id })
  return (
    <section
      ref={setNodeRef}
      data-slot="task-column"
      aria-label={label}
      className={cn(
        "flex w-72 max-w-full shrink-0 snap-start flex-col gap-2 rounded-xl bg-muted/40 p-2",
        isOver && "ring-2 ring-ring",
        className,
      )}
    >
      {children}
    </section>
  )
}

function SortableTask<TMeta extends Record<string, unknown>>({
  task,
  reduced,
  disabled,
  cardClassName,
  people,
  stages,
  priorities,
  overdue,
  locale,
  labels,
  selected,
  onOpen,
  onMoveTo,
}: {
  task: TaskRecord<TMeta>
  reduced: boolean
  disabled: boolean
  cardClassName?: string
  people: readonly TaskPerson[]
  stages: readonly TaskOption[]
  priorities: readonly { id: TaskPriority; label: string }[]
  overdue: boolean
  locale: string
  labels: TaskBoardLabels
  selected: boolean
  onOpen: (id: string) => void
  onMoveTo: (stageId: string) => void
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: task.id,
    disabled,
  })
  const style: React.CSSProperties = {
    transform: DndCSS.Transform.toString(transform),
    transition: reduced ? undefined : transition,
  }
  const priorityLabel = priorities.find((item) => item.id === task.priority)?.label
  return (
    <div ref={setNodeRef} style={style} className={cn(isDragging && "opacity-40")}>
      <TaskCard
        task={task}
        people={people}
        stages={stages}
        priorityLabel={priorityLabel}
        overdue={overdue}
        locale={locale}
        labels={labels}
        readOnly={disabled}
        selected={selected}
        onOpen={onOpen}
        onMoveTo={onMoveTo}
        dragHandleProps={disabled ? undefined : { ...attributes, ...listeners }}
        className={cn("motion-reduce:transition-none", cardClassName)}
      />
    </div>
  )
}

export type {
  TaskAttachment,
  TaskBoardLabels,
  TaskBoardView,
  TaskComment,
  TaskCommentInput,
  TaskOption,
  TaskPatch,
  TaskPerson,
  TaskPriority,
  TaskRecord,
  TaskSubtask,
  TaskSubtaskDraft,
} from "@/lib/task-board"

"use client"

/**
 * Clean-room task card. Host semantic classes only.
 * Assignees use the host Avatar so a dense board does not add a tab stop per person.
 * `avatar-group` stays the interactive stack.
 */

import * as React from "react"
import { AlertTriangle, Calendar, GripVertical, ListChecks, MessageSquare, MoreHorizontal } from "lucide-react"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { PriorityBadge } from "@/components/ui/priority-badge"
import {
  formatTaskDate,
  resolveTaskBoardLabels,
  type TaskBoardLabels,
  type TaskOption,
  type TaskPerson,
  type TaskRecord,
} from "@/lib/task-board"

export type TaskCardProps<TMeta = Record<string, unknown>> = {
  task: TaskRecord<TMeta>
  people?: readonly TaskPerson[]
  stages?: readonly TaskOption[]
  priorityLabel?: string
  overdue?: boolean
  locale?: string
  labels?: Partial<TaskBoardLabels>
  readOnly?: boolean
  selected?: boolean
  onOpen?: (id: string) => void
  onMoveTo?: (stageId: string) => void
  /** Listeners from a drag sensor. Omitted, the handle stays disabled. */
  dragHandleProps?: React.HTMLAttributes<HTMLButtonElement>
  className?: string
}

function initials(name: string) {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

function isRtl(node: HTMLElement) {
  return getComputedStyle(node).direction === "rtl"
}

export function TaskCard<TMeta extends Record<string, unknown> = Record<string, unknown>>({
  task,
  people = [],
  stages = [],
  priorityLabel,
  overdue = false,
  locale = "es",
  labels: labelOverrides,
  readOnly = false,
  selected = false,
  onOpen,
  onMoveTo,
  dragHandleProps,
  className,
}: TaskCardProps<TMeta>) {
  const labels = resolveTaskBoardLabels(labelOverrides)
  const assignees = task.assigneeIds
    .map((id) => people.find((person) => person.id === id))
    .filter((person): person is TaskPerson => Boolean(person))
  const visible = assignees.slice(0, 3)
  const extra = assignees.length - visible.length
  const due = formatTaskDate(task.dueAt, locale, "short")
  const subtaskCount = task.subtasks?.length ?? 0
  const commentCount = task.comments?.length ?? 0
  const assigneeLabel = labels.assignees(assignees.map((person) => person.name))

  function onTitleKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    if (readOnly || !onMoveTo) return
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return
    const index = stages.findIndex((stage) => stage.id === task.stageId)
    if (index < 0) return
    const forward = event.key === "ArrowRight" ? 1 : -1
    const delta = isRtl(event.currentTarget) ? -forward : forward
    const next = stages[index + delta]
    if (!next) return
    event.preventDefault()
    onMoveTo(next.id)
  }

  return (
    <article
      data-slot="task-card"
      data-task-id={task.id}
      data-stage-id={task.stageId}
      data-overdue={overdue ? "true" : "false"}
      data-selected={selected ? "true" : "false"}
      className={cn(
        "rounded-lg border border-border bg-card p-3 text-card-foreground shadow-sm",
        selected && "ring-2 ring-ring",
        className,
      )}
    >
      <div className="flex items-start gap-1.5">
        <button
          type="button"
          className="mt-0.5 text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:cursor-default"
          aria-label={labels.dragTask(task.title)}
          {...(readOnly ? {} : dragHandleProps)}
          disabled={readOnly || !dragHandleProps}
        >
          <GripVertical className="size-3.5" aria-hidden />
        </button>
        <div className="min-w-0 flex-1">
          <button
            type="button"
            data-task-focus={task.id}
            className="w-full rounded-sm text-left focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
            aria-label={labels.openTask(task.title)}
            onClick={() => onOpen?.(task.id)}
            onKeyDown={onTitleKeyDown}
          >
            <span className="line-clamp-3 text-sm font-medium break-all" dir="auto">
              {task.title}
            </span>
          </button>
          <div className="mt-2 flex flex-wrap items-center gap-1.5">
            <PriorityBadge level={task.priority} label={priorityLabel} />
            {overdue ? (
              <span className="inline-flex h-6 items-center gap-1 rounded-full bg-destructive/10 px-2 text-xs font-medium text-destructive">
                <AlertTriangle className="size-3" aria-hidden />
                {labels.overdue}
              </span>
            ) : null}
          </div>
          <div className="mt-2 flex items-center justify-between gap-2">
            <div className="flex min-w-0 items-center" role="group" aria-label={assigneeLabel}>
              {visible.length === 0 ? (
                <span className="text-xs text-muted-foreground">{labels.unassigned}</span>
              ) : (
                visible.map((person) => (
                  <Avatar key={person.id} size="sm" className="-ms-1.5 ring-2 ring-background first:ms-0">
                    {person.src ? <AvatarImage src={person.src} alt="" /> : null}
                    <AvatarFallback className="text-[10px]">{initials(person.name)}</AvatarFallback>
                  </Avatar>
                ))
              )}
              {extra > 0 ? (
                <span className="-ms-1.5 inline-grid size-6 place-items-center rounded-full bg-muted text-[10px] font-medium text-muted-foreground ring-2 ring-background tabular-nums">
                  +{extra}
                </span>
              ) : null}
            </div>
            {due ? (
              <span className="inline-flex shrink-0 items-center gap-1 text-xs text-muted-foreground tabular-nums">
                <Calendar className="size-3.5" aria-hidden />
                <span>{labels.dueOn(due)}</span>
              </span>
            ) : null}
          </div>
          <div className="mt-2 flex flex-wrap gap-3 text-xs text-muted-foreground">
            <span className="inline-flex items-center gap-1">
              <ListChecks className="size-3.5" aria-hidden />
              {labels.subtasks(subtaskCount)}
            </span>
            <span className="inline-flex items-center gap-1">
              <MessageSquare className="size-3.5" aria-hidden />
              {labels.comments(commentCount)}
            </span>
          </div>
        </div>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.actionsFor(task.title)}>
              <MoreHorizontal aria-hidden />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onSelect={() => onOpen?.(task.id)}>{labels.open}</DropdownMenuItem>
            {readOnly ? null : (
              <>
                <DropdownMenuLabel>{labels.moveTo}</DropdownMenuLabel>
                {stages.map((stage) => (
                  <DropdownMenuItem
                    key={stage.id}
                    disabled={stage.id === task.stageId}
                    onSelect={() => onMoveTo?.(stage.id)}
                  >
                    {stage.label}
                  </DropdownMenuItem>
                ))}
              </>
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </article>
  )
}

"use client"

/**
 * Clean-room task detail. Fields, subtasks, comments, reminder, and attachments.
 * The host saves through callbacks. This file does not fetch.
 */

import * as React from "react"
import {
  Bell,
  Calendar,
  ChevronLeft,
  ChevronRight,
  ListChecks,
  MessageSquare,
  Paperclip,
  Pencil,
  Plus,
  Send,
  Tag,
  Users,
  X,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { PriorityBadge } from "@/components/ui/priority-badge"
import {
  defaultPriorities,
  defaultSubtaskStatuses,
  formatFileSize,
  formatTaskDate,
  fromDateTimeLocal,
  isTaskPriority,
  personName,
  resolveTaskBoardLabels,
  threadComments,
  toDateTimeLocal,
  type TaskBoardLabels,
  type TaskComment,
  type TaskCommentInput,
  type TaskOption,
  type TaskPatch,
  type TaskPerson,
  type TaskPriority,
  type TaskRecord,
  type TaskSubtaskDraft,
} from "@/lib/task-board"

const selectClass =
  "h-8 w-full min-w-0 rounded-lg border border-input bg-transparent px-2 text-sm text-foreground outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50"

export type TaskDetailProps<TMeta = Record<string, unknown>> = {
  task: TaskRecord<TMeta>
  people?: readonly TaskPerson[]
  stages?: readonly TaskOption[]
  categories?: readonly TaskOption[]
  priorities?: readonly { id: TaskPriority; label: string }[]
  subtaskStatuses?: readonly TaskOption[]
  /** 1-based index in the ordered collection. */
  position?: number
  total?: number
  locale?: string
  labels?: Partial<TaskBoardLabels>
  readOnly?: boolean
  onClose?: () => void
  onPrevious?: () => void
  onNext?: () => void
  onUpdate?: (id: string, patch: TaskPatch<TMeta>) => void | Promise<void>
  onStageChange?: (stageId: string) => void
  onAddSubtask?: (id: string, draft: TaskSubtaskDraft) => void | Promise<void>
  onSubtaskStatusChange?: (taskId: string, subtaskId: string, statusId: string) => void | Promise<void>
  onComment?: (id: string, input: TaskCommentInput) => void | Promise<void>
  onAttach?: (id: string, files: readonly File[]) => void | Promise<void>
  onRemoveAttachment?: (taskId: string, attachmentId: string) => void | Promise<void>
  className?: string
}

export function TaskDetail<TMeta extends Record<string, unknown> = Record<string, unknown>>(props: TaskDetailProps<TMeta>) {
  return <TaskDetailForm key={props.task.id} {...props} />
}

function TaskDetailForm<TMeta extends Record<string, unknown> = Record<string, unknown>>({
  task,
  people = [],
  stages = [],
  categories = [],
  priorities,
  subtaskStatuses,
  position = 1,
  total = 1,
  locale = "es",
  labels: labelOverrides,
  readOnly = false,
  onClose,
  onPrevious,
  onNext,
  onUpdate,
  onStageChange,
  onAddSubtask,
  onSubtaskStatusChange,
  onComment,
  onAttach,
  onRemoveAttachment,
  className,
}: TaskDetailProps<TMeta>) {
  const labels = resolveTaskBoardLabels(labelOverrides)
  const priorityOptions = priorities ?? defaultPriorities(labels)
  const statusOptions = subtaskStatuses ?? defaultSubtaskStatuses(labels)
  const threads = threadComments(task.comments)
  const [expanded, setExpanded] = React.useState(false)
  const [editing, setEditing] = React.useState(false)
  const [description, setDescription] = React.useState(task.description ?? "")
  const [subtaskTitle, setSubtaskTitle] = React.useState("")
  const [body, setBody] = React.useState("")
  const [parentId, setParentId] = React.useState<string | null>(null)
  const [files, setFiles] = React.useState<File[]>([])
  const fileRef = React.useRef<HTMLInputElement>(null)
  const commentRef = React.useRef<HTMLTextAreaElement>(null)
  const long = (task.description ?? "").length > 180

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.altKey || event.metaKey || event.ctrlKey || event.shiftKey) return
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return
    const target = event.target
    if (!(target instanceof HTMLElement)) return
    if (target.closest("input, textarea, select, [contenteditable='true']")) return
    if (event.key === "ArrowLeft" && onPrevious) {
      event.preventDefault()
      onPrevious()
    }
    if (event.key === "ArrowRight" && onNext) {
      event.preventDefault()
      onNext()
    }
  }

  function patch(next: TaskPatch<TMeta>) {
    if (readOnly) return
    void onUpdate?.(task.id, next)
  }

  function addSubtask(event: React.FormEvent) {
    event.preventDefault()
    const title = subtaskTitle.trim()
    if (!title || readOnly) return
    void onAddSubtask?.(task.id, { title, statusId: statusOptions[0]?.id, priority: "medium" })
    setSubtaskTitle("")
  }

  function sendComment() {
    if (readOnly) return
    const text = body.trim()
    if (!text && files.length === 0) return
    if (text) void onComment?.(task.id, { body: text, parentId, files })
    else void onAttach?.(task.id, files)
    setBody("")
    setParentId(null)
    setFiles([])
  }

  function onCommentKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key !== "Enter" || !(event.metaKey || event.ctrlKey)) return
    event.preventDefault()
    sendComment()
  }

  const parent = parentId ? task.comments?.find((comment) => comment.id === parentId) : undefined
  const parentName = parent ? personName(people, parent.authorId, labels.unknownAuthor) : ""

  return (
    <div
      data-slot="task-detail"
      className={cn("flex h-full w-full min-h-0 min-w-0 flex-col bg-popover text-popover-foreground", className)}
      onKeyDown={onKeyDown}
    >
      <header className="flex shrink-0 items-start gap-2 border-b border-border px-4 py-3">
        <div className="min-w-0 flex-1">
          <p className="text-xs font-medium text-muted-foreground">{labels.detailTitle}</p>
          <h2 className="text-base font-semibold break-all" dir="auto">
            {task.title}
          </h2>
        </div>
        <div className="flex shrink-0 items-center gap-1">
          <Button
            type="button"
            variant="outline"
            size="icon-sm"
            aria-label={labels.previous}
            aria-keyshortcuts="ArrowLeft"
            disabled={!onPrevious}
            onClick={onPrevious}
          >
            <ChevronLeft aria-hidden />
          </Button>
          <Button
            type="button"
            variant="outline"
            size="icon-sm"
            aria-label={labels.next}
            aria-keyshortcuts="ArrowRight"
            disabled={!onNext}
            onClick={onNext}
          >
            <ChevronRight aria-hidden />
          </Button>
          <span className="px-1 text-xs text-muted-foreground tabular-nums">{labels.position(position, total)}</span>
          {onClose ? (
            <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.close} onClick={onClose}>
              <X aria-hidden />
            </Button>
          ) : null}
        </div>
      </header>
      <p className="sr-only">{labels.shortcuts}</p>
      <div className="min-h-0 flex-1 overflow-y-auto px-4 py-4">
        <div className="grid gap-3">
          <Field icon={<Calendar aria-hidden />} label={labels.due}>
            <div className="flex min-w-0 items-center gap-2">
              <Input
                type="datetime-local"
                className="min-w-0 flex-1"
                aria-label={labels.due}
                value={toDateTimeLocal(task.dueAt)}
                disabled={readOnly}
                onChange={(event) => patch({ dueAt: fromDateTimeLocal(event.target.value) })}
              />
              {task.dueAt && !readOnly ? (
                <Button type="button" variant="ghost" size="sm" onClick={() => patch({ dueAt: null })}>
                  {labels.clearValue}
                </Button>
              ) : null}
            </div>
            {task.dueAt ? (
              <p className="mt-1 text-xs text-muted-foreground">{formatTaskDate(task.dueAt, locale)}</p>
            ) : null}
          </Field>
          {categories.length > 0 ? (
            <Field icon={<Tag aria-hidden />} label={labels.category}>
              <select
                className={selectClass}
                aria-label={labels.category}
                value={task.categoryId ?? ""}
                disabled={readOnly}
                onChange={(event) => patch({ categoryId: event.target.value || null })}
              >
                <option value="">{labels.noCategory}</option>
                {categories.map((category) => (
                  <option key={category.id} value={category.id}>
                    {category.label}
                  </option>
                ))}
              </select>
            </Field>
          ) : null}
          <Field icon={<PriorityBadge level={task.priority} variant="glyph" />} label={labels.priority}>
            <select
              className={selectClass}
              aria-label={labels.priority}
              value={task.priority}
              disabled={readOnly}
              onChange={(event) => {
                if (isTaskPriority(event.target.value)) patch({ priority: event.target.value })
              }}
            >
              {priorityOptions.map((priority) => (
                <option key={priority.id} value={priority.id}>
                  {priority.label}
                </option>
              ))}
            </select>
          </Field>
          {stages.length > 0 ? (
            <Field icon={<ListChecks aria-hidden />} label={labels.stage}>
              <select
                className={selectClass}
                aria-label={labels.stage}
                value={task.stageId}
                disabled={readOnly}
                onChange={(event) => onStageChange?.(event.target.value)}
              >
                {stages.map((stage) => (
                  <option key={stage.id} value={stage.id}>
                    {stage.label}
                  </option>
                ))}
                {stages.some((stage) => stage.id === task.stageId) ? null : (
                  <option value={task.stageId}>{task.stageId}</option>
                )}
              </select>
            </Field>
          ) : null}
          <Field icon={<Bell aria-hidden />} label={labels.reminder}>
            <div className="flex min-w-0 items-center gap-2">
              <Input
                type="datetime-local"
                className="min-w-0 flex-1"
                aria-label={labels.reminder}
                value={toDateTimeLocal(task.reminderAt)}
                disabled={readOnly}
                onChange={(event) => patch({ reminderAt: fromDateTimeLocal(event.target.value) })}
              />
              {task.reminderAt && !readOnly ? (
                <Button type="button" variant="ghost" size="sm" onClick={() => patch({ reminderAt: null })}>
                  {labels.clearValue}
                </Button>
              ) : null}
            </div>
          </Field>
          {people.length > 0 ? (
            <Field icon={<Users aria-hidden />} label={labels.assigneesLabel}>
              <fieldset>
                <legend className="sr-only">{labels.assigneesLabel}</legend>
                <div className="flex flex-wrap gap-1.5">
                  {people.map((person) => {
                    const checked = task.assigneeIds.includes(person.id)
                    return (
                      <label
                        key={person.id}
                        className="inline-flex max-w-full items-center gap-1.5 rounded-full border border-border px-2 py-1 text-xs"
                      >
                        <Checkbox
                          checked={checked}
                          disabled={readOnly}
                          onCheckedChange={(value) => {
                            const assigneeIds = value
                              ? [...task.assigneeIds, person.id]
                              : task.assigneeIds.filter((id) => id !== person.id)
                            patch({ assigneeIds })
                          }}
                        />
                        <span className="truncate" dir="auto">
                          {person.name}
                        </span>
                      </label>
                    )
                  })}
                </div>
              </fieldset>
            </Field>
          ) : null}
          <Field icon={<MessageSquare aria-hidden />} label={labels.description}>
            {editing ? (
              <div className="grid gap-2">
                <Textarea
                  aria-label={labels.description}
                  value={description}
                  onChange={(event) => setDescription(event.target.value)}
                  rows={5}
                  className="break-all"
                />
                <div className="flex gap-2">
                  <Button
                    type="button"
                    size="sm"
                    onClick={() => {
                      patch({ description })
                      setEditing(false)
                    }}
                  >
                    {labels.save}
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    variant="ghost"
                    onClick={() => {
                      setDescription(task.description ?? "")
                      setEditing(false)
                    }}
                  >
                    {labels.cancel}
                  </Button>
                </div>
              </div>
            ) : (
              <div className="grid gap-1">
                <p className={cn("text-sm break-all whitespace-pre-wrap", long && !expanded && "line-clamp-3")} dir="auto">
                  {task.description || labels.noDescription}
                </p>
                <div className="flex flex-wrap gap-2">
                  {long ? (
                    <Button type="button" variant="link" size="sm" className="h-auto px-0" onClick={() => setExpanded((value) => !value)}>
                      {expanded ? labels.readLess : labels.readMore}
                    </Button>
                  ) : null}
                  {readOnly ? null : (
                    <Button type="button" variant="ghost" size="sm" onClick={() => setEditing(true)}>
                      <Pencil aria-hidden />
                      {labels.editDescription}
                    </Button>
                  )}
                </div>
              </div>
            )}
          </Field>
        </div>

        <section className="mt-6" aria-labelledby="task-subtasks-heading">
          <div className="flex items-center justify-between gap-2">
            <h3 id="task-subtasks-heading" className="text-sm font-medium">
              {labels.subtasksTitle(task.subtasks?.length ?? 0)}
            </h3>
          </div>
          {readOnly ? null : (
            <form className="mt-2 flex min-w-0 items-center gap-2" onSubmit={addSubtask}>
              <Input
                className="min-w-0 flex-1"
                value={subtaskTitle}
                onChange={(event) => setSubtaskTitle(event.target.value)}
                placeholder={labels.subtaskPlaceholder}
                aria-label={labels.subtaskPlaceholder}
              />
              <Button type="submit" size="sm" className="shrink-0" disabled={!subtaskTitle.trim()}>
                <Plus aria-hidden />
                {labels.addSubtask}
              </Button>
            </form>
          )}
          {task.subtasks?.length ? (
            <ul className="mt-3 grid gap-2">
              {task.subtasks.map((subtask) => (
                <li key={subtask.id} className="rounded-lg border border-border p-2">
                  <div className="flex items-start justify-between gap-2">
                    <p className="min-w-0 text-sm font-medium break-all" dir="auto">
                      {subtask.title}
                    </p>
                    {subtask.priority ? (
                      <PriorityBadge
                        level={subtask.priority}
                        label={priorityOptions.find((item) => item.id === subtask.priority)?.label}
                      />
                    ) : null}
                  </div>
                  {subtask.description ? (
                    <p className="mt-1 text-xs text-muted-foreground break-all" dir="auto">
                      {subtask.description}
                    </p>
                  ) : null}
                  <select
                    className={cn(selectClass, "mt-2")}
                    aria-label={labels.subtaskStatus(subtask.title)}
                    value={subtask.statusId}
                    disabled={readOnly}
                    onChange={(event) => void onSubtaskStatusChange?.(task.id, subtask.id, event.target.value)}
                  >
                    {statusOptions.some((status) => status.id === subtask.statusId) ? null : (
                      <option value={subtask.statusId}>{subtask.statusId}</option>
                    )}
                    {statusOptions.map((status) => (
                      <option key={status.id} value={status.id}>
                        {status.label}
                      </option>
                    ))}
                  </select>
                </li>
              ))}
            </ul>
          ) : (
            <p className="mt-2 text-sm text-muted-foreground">{labels.noSubtasks}</p>
          )}
        </section>

        {(task.attachments?.length ?? 0) > 0 ? (
          <section className="mt-6" aria-labelledby="task-attachments-heading">
            <h3 id="task-attachments-heading" className="text-sm font-medium">
              {labels.attachments}
            </h3>
            <ul className="mt-2 grid gap-1">
              {task.attachments?.map((file) => (
                <li key={file.id} className="flex items-center gap-2 text-sm">
                  <Paperclip className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />
                  {file.href ? (
                    <a className="min-w-0 truncate underline-offset-4 hover:underline" href={file.href} dir="auto">
                      {file.name}
                    </a>
                  ) : (
                    <span className="min-w-0 truncate" dir="auto">
                      {file.name}
                    </span>
                  )}
                  {typeof file.size === "number" ? (
                    <span className="text-xs text-muted-foreground tabular-nums">{formatFileSize(file.size)}</span>
                  ) : null}
                  {readOnly ? null : (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="ms-auto"
                      onClick={() => void onRemoveAttachment?.(task.id, file.id)}
                    >
                      {labels.removeAttachment(file.name)}
                    </Button>
                  )}
                </li>
              ))}
            </ul>
          </section>
        ) : null}

        <section className="mt-6" aria-labelledby="task-comments-heading">
          <h3 id="task-comments-heading" className="text-sm font-medium">
            {labels.commentsTitle}
          </h3>
          {threads.length === 0 ? <p className="mt-2 text-sm text-muted-foreground">{labels.noComments}</p> : null}
          <ol className="mt-3 grid gap-4">
            {threads.map(({ comment, replies }) => (
              <li key={comment.id}>
                <CommentBlock
                  comment={comment}
                  people={people}
                  locale={locale}
                  labels={labels}
                  readOnly={readOnly}
                  onReply={() => {
                    setParentId(comment.id)
                    commentRef.current?.focus()
                  }}
                />
                {replies.length > 0 ? (
                  <ul className="mt-3 grid gap-3 border-s border-border ps-3">
                    {replies.map((reply) => (
                      <li key={reply.id}>
                        <CommentBlock comment={reply} people={people} locale={locale} labels={labels} readOnly />
                      </li>
                    ))}
                  </ul>
                ) : null}
              </li>
            ))}
          </ol>
          {readOnly ? null : (
            <div className="mt-4 grid gap-2">
              {parentId ? (
                <div className="flex items-center justify-between gap-2 text-xs text-muted-foreground">
                  <span>{labels.replyingTo(parentName)}</span>
                  <Button type="button" variant="ghost" size="sm" onClick={() => setParentId(null)}>
                    {labels.cancelReply}
                  </Button>
                </div>
              ) : null}
              <Textarea
                ref={commentRef}
                value={body}
                onChange={(event) => setBody(event.target.value)}
                onKeyDown={onCommentKeyDown}
                placeholder={labels.commentPlaceholder}
                aria-label={labels.commentPlaceholder}
                rows={3}
              />
              {files.length > 0 ? (
                <ul className="grid gap-1">
                  {files.map((file) => (
                    <li key={`${file.name}-${file.size}`} className="flex items-center gap-2 text-xs">
                      <span className="min-w-0 truncate" dir="auto">
                        {file.name}
                      </span>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => setFiles((current) => current.filter((item) => item !== file))}
                      >
                        {labels.removePendingFile(file.name)}
                      </Button>
                    </li>
                  ))}
                </ul>
              ) : null}
              <div className="flex items-center justify-end gap-2">
                <input
                  ref={fileRef}
                  type="file"
                  multiple
                  className="sr-only"
                  aria-label={labels.attach}
                  onChange={(event) => {
                    const list = Array.from(event.target.files ?? [])
                    setFiles((current) => [...current, ...list])
                    event.target.value = ""
                  }}
                />
                <Button type="button" variant="outline" size="icon-sm" aria-label={labels.attach} onClick={() => fileRef.current?.click()}>
                  <Paperclip aria-hidden />
                </Button>
                <Button type="button" size="sm" onClick={sendComment} disabled={!body.trim() && files.length === 0}>
                  <Send aria-hidden />
                  {labels.send}
                </Button>
              </div>
            </div>
          )}
        </section>
      </div>
    </div>
  )
}

function Field({
  icon,
  label,
  children,
}: {
  icon: React.ReactNode
  label: string
  children: React.ReactNode
}) {
  return (
    <div className="grid gap-1.5 sm:grid-cols-[9.5rem_minmax(0,1fr)] sm:items-start sm:gap-3">
      <div className="flex items-center gap-2 text-sm text-muted-foreground">
        <span className="inline-flex size-4 shrink-0 items-center justify-center">{icon}</span>
        <span>{label}</span>
      </div>
      <div className="min-w-0">{children}</div>
    </div>
  )
}

function CommentBlock({
  comment,
  people,
  locale,
  labels,
  readOnly,
  onReply,
}: {
  comment: TaskComment
  people: readonly TaskPerson[]
  locale: string
  labels: TaskBoardLabels
  readOnly?: boolean
  onReply?: () => void
}) {
  const name = personName(people, comment.authorId, labels.unknownAuthor)
  return (
    <article className="grid gap-1" aria-label={name}>
      <div className="flex flex-wrap items-baseline gap-2">
        <span className="text-sm font-medium" dir="auto">
          {name}
        </span>
        <time className="text-xs text-muted-foreground" dateTime={comment.createdAt}>
          {formatTaskDate(comment.createdAt, locale)}
        </time>
      </div>
      <p className="text-sm break-all whitespace-pre-wrap" dir="auto">
        {comment.body}
      </p>
      {onReply && !readOnly ? (
        <Button type="button" variant="link" size="sm" className="h-auto justify-start px-0" onClick={onReply}>
          {labels.reply}
        </Button>
      ) : null}
    </article>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"

export const PRIORITY_LEVELS = ["low", "medium", "high", "critical"] as const

export type PriorityLevel = (typeof PRIORITY_LEVELS)[number]

export type PriorityBadgeClassNames = {
  root?: string | undefined
  glyph?: string | undefined
  label?: string | undefined
}

export type PriorityBadgeProps = {
  level: PriorityLevel
  label?: string | undefined
  variant?: "chip" | "glyph" | "pill" | undefined
  /** Pill only. Soft keeps a wash. Solid fills high and critical. */
  appearance?: "soft" | "solid" | undefined
  className?: string | undefined
  classNames?: PriorityBadgeClassNames | undefined
}

const DEFAULT_LABEL: Record<PriorityLevel, string> = {
  low: "Low",
  medium: "Medium",
  high: "High",
  critical: "Critical",
}

export function priorityRank(level: PriorityLevel): number {
  return PRIORITY_LEVELS.indexOf(level) + 1
}

export function comparePriority(a: PriorityLevel, b: PriorityLevel): number {
  return priorityRank(a) - priorityRank(b)
}

function SignalGlyph({ filled, className }: { filled: number; className?: string | undefined }) {
  const heights = [4, 7, 10, 13]
  return (
    <svg viewBox="0 0 16 14" className={cn("h-3.5 w-4", className)} aria-hidden>
      {heights.map((height, index) => (
        <rect
          key={height}
          x={index * 4}
          y={14 - height}
          width="2.5"
          height={height}
          rx="0.5"
          className={index < filled ? "fill-current" : "fill-current opacity-30"}
        />
      ))}
    </svg>
  )
}

export function PriorityBadge({
  level,
  label,
  variant = "chip",
  appearance,
  className,
  classNames,
}: PriorityBadgeProps) {
  const text = label ?? DEFAULT_LABEL[level]
  const critical = level === "critical"
  if (variant === "pill") {
    const solid = appearance === "solid" || (appearance !== "soft" && (level === "high" || level === "critical"))
    return (
      <span
        data-slot="priority-badge"
        data-level={level}
        data-variant="pill"
        className={cn(
          "inline-flex h-6 max-w-full items-center rounded-full px-2 text-xs font-medium",
          solid && (level === "high" || level === "critical") && "bg-destructive text-background",
          solid && level !== "high" && level !== "critical" && "bg-foreground text-background",
          !solid && (level === "critical" || level === "high") && "bg-destructive/10 text-destructive",
          !solid && level === "medium" && "bg-chart-4/15 text-foreground",
          !solid && level === "low" && "bg-muted text-foreground",
          className,
          classNames?.root,
        )}
      >
        <span className={cn("truncate", classNames?.label)}>{text}</span>
      </span>
    )
  }
  if (variant === "glyph") {
    return (
      <span className={cn("inline-flex text-foreground", critical && "text-destructive", className, classNames?.root)} aria-label={text}>
        <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      </span>
    )
  }
  return (
    <span
      data-slot="priority-badge"
      data-level={level}
      className={cn(
        "inline-flex h-6 max-w-full items-center gap-1 rounded-full px-2 text-xs font-medium",
        critical ? "bg-destructive/10 text-destructive" : "bg-muted text-foreground",
        className,
        classNames?.root,
      )}
    >
      <SignalGlyph filled={priorityRank(level)} className={classNames?.glyph} />
      <span className={cn("truncate", classNames?.label)}>{text}</span>
    </span>
  )
}

