/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Search, X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type SearchFieldClassNames = {
  root?: string
  label?: string
  shell?: string
  input?: string
  clear?: string
}

export type SearchFieldProps = Omit<React.ComponentProps<"input">, "type" | "value" | "onChange"> & {
  label: string
  value: string
  onValueChange: (value: string) => void
  classNames?: SearchFieldClassNames
}

export const SearchField = React.forwardRef<HTMLInputElement, SearchFieldProps>(function SearchField(
  { label, value, onValueChange, id, className, classNames, ...props },
  ref,
) {
  const generated = React.useId()
  const controlId = id ?? generated
  const reduced = useReducedMotion()
  const inputRef = React.useRef<HTMLInputElement | null>(null)

  const setRefs = (node: HTMLInputElement | null) => {
    inputRef.current = node
    if (typeof ref === "function") ref(node)
    else if (ref) ref.current = node
  }

  function clear() {
    onValueChange("")
    inputRef.current?.focus()
  }

  return (
    <div data-slot="search-field" className={cn("grid min-w-0 gap-2", className, classNames?.root)}>
      <label htmlFor={controlId} data-slot="search-field-label" className={cn("text-sm font-medium", classNames?.label)}>
        {label}
      </label>
      <div
        data-slot="search-field-shell"
        data-filled={value ? "true" : undefined}
        className={cn(
          "flex h-9 min-w-0 items-center gap-1 rounded-lg border border-input bg-transparent pr-1 pl-2.5 focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50",
          classNames?.shell,
        )}
      >
        <Search className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
        <Input
          {...props}
          ref={setRefs}
          id={controlId}
          type="search"
          value={value}
          onChange={(event) => onValueChange(event.target.value)}
          className={cn(
            "h-8 border-0 bg-transparent px-1 shadow-none focus-visible:ring-0 dark:bg-transparent [&::-webkit-search-cancel-button]:appearance-none",
            classNames?.input,
          )}
        />
        <span className="grid size-6 shrink-0 place-items-center">
          <AnimatePresence initial={false}>
            {value ? (
              <motion.span
                key="clear"
                initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, scale: 0.8 }}
                transition={reduced ? { duration: motionPresets.duration.instant } : motionPresets.spring.snappy}
              >
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-xs"
                  data-slot="search-field-clear"
                  className={classNames?.clear}
                  aria-label="Clear search"
                  onClick={clear}
                >
                  <X aria-hidden="true" />
                </Button>
              </motion.span>
            ) : null}
          </AnimatePresence>
        </span>
      </div>
    </div>
  )
})

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
  /** Drawn before the label. With `iconsOnly`, the label stays available to assistive tech. */
  icon?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  /** Hides each label visually and keeps it in the accessible name. */
  iconsOnly?: boolean
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  iconsOnly = false,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.icon}
                  {iconsOnly ? <span className="sr-only">{option.label}</span> : option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
